#include <bits/stdc++.h>
using namespace std;

int main() {

	int N,M;
	cin>>N>>M;
	vector<vector<int>> E(N);

	for(int i=0;i<M;i++){
		int u,v;
		cin>>u>>v;
		E[u-1].push_back(v-1);
	}

	int ans = 0;

	for(int i=0;i<N;i++){
		vector<bool> f(N,false);
		f[i] = true;
		queue<int> Q;
		Q.push(i);

		while(Q.size()>0){
			int x = Q.front();
			Q.pop();
			for(int j=0;j<E[x].size();j++){
				int y = E[x][j];
				if(f[y])continue;
				f[y] = true;
				Q.push(y);
				ans++;
			}
		}
	}

	ans -= M;
	cout<<ans<<endl;

	return 0;
}

use fixedbitset::FixedBitSet;
use proconio::{input, marker::Usize1};

fn main() {
    input! {
        n: usize,
        m: usize,
        edges: [(Usize1, Usize1); m],
    }
    let mut trans = vec![FixedBitSet::with_capacity(n); n];
    (0..n).for_each(|i| trans[i].insert(i));
    for &(i, j) in &edges {
        trans[i].insert(j);
    }
    for j in 0..n {
        for i in 0..n {
            if trans[i][j] {
                let x = trans[j].clone();
                trans[i] |= x;
            }
        }
    }
    let ans = trans.iter().map(|row| row.count_ones(..)).sum::<usize>() - m - n;
    println!("{}", ans);
}
